<?php
declare(strict_types=1);
use Medbiohim\Http\Request;use Medbiohim\Http\Response;use Medbiohim\Http\Router;use Medbiohim\Middleware\RequireAuth;use Medbiohim\Middleware\RequireRole;use Medbiohim\Repositories\HomeworkRepository;use Medbiohim\Services\SupabaseAcademic;use Medbiohim\Services\SupabaseRest;
return static function(Router $router):void{
$router->get('/api/v1/homeworks',static function(Request $req,array $params):void{if(!RequireAuth::handle($req))return;try{Response::success(['items'=>(new HomeworkRepository())->listForUser($req->user->id)],$req->requestId);}catch(\Throwable $e){try{Response::success(['items'=>SupabaseAcademic::homeworksForUser($req->user->id)],$req->requestId);}catch(\Throwable $x){try{Response::success(['items'=>SupabaseRest::listHomeworksForUser($req->user->id)],$req->requestId);}catch(\Throwable $z){\Medbiohim\Support\Logger::error('homeworks_list_failed',['requestId'=>$req->requestId,'db'=>$e->getMessage(),'academic'=>$x->getMessage(),'rest'=>$z->getMessage()]);\Medbiohim\Support\Logger::error('homeworks_soft_empty',['requestId'=>$req->requestId]);Response::success(['items'=>[],'note'=>'Database unavailable — set DB_URL (Session pooler) on SpaceWeb'],$req->requestId);}}}});
$router->post('/api/v1/homeworks',static function(Request $req,array $params):void{if(!RequireAuth::handle($req))return;if(!RequireRole::handle($req,['teacher','moderator','admin']))return;$title=trim((string)$req->json('title',''));if($title===''){Response::error('VALIDATION_ERROR','title is required',$req->requestId,422);return;}try{$row=(new HomeworkRepository())->create($title,$req->json('description')!==null?(string)$req->json('description'):null,$req->json('subject_id')?(string)$req->json('subject_id'):null,$req->json('group_id')?(string)$req->json('group_id'):null,$req->json('due_at')?(string)$req->json('due_at'):null,$req->user->id);Response::success($row,$req->requestId,201);}catch(\Throwable $e){try{$row=SupabaseRest::createHomework(['title'=>$title,'description'=>$req->json('description')!==null?(string)$req->json('description'):null,'subject_id'=>$req->json('subject_id')?(string)$req->json('subject_id'):null,'group_id'=>$req->json('group_id')?(string)$req->json('group_id'):null,'due_at'=>$req->json('due_at')?(string)$req->json('due_at'):null,'created_by'=>$req->user->id]);Response::success($row,$req->requestId,201);}catch(\Throwable $x){Response::error('DB_ERROR','Could not create homework',$req->requestId,500);}}});
$router->post('/api/v1/homeworks/{id}/submit',static function(Request $req,array $params):void{if(!RequireAuth::handle($req))return;try{$hw=(new HomeworkRepository())->findById($params['id']);if($hw===null){Response::error('NOT_FOUND','Homework not found',$req->requestId,404);return;}$row=(new HomeworkRepository())->submit($params['id'],$req->user->id,$req->json('text_answer')!==null?(string)$req->json('text_answer'):null,$req->json('file_id')?(string)$req->json('file_id'):null);Response::success(['submission'=>$row],$req->requestId,201);}catch(\Throwable $e){try{$row=SupabaseRest::submitHomework($params['id'],$req->user->id,$req->json('text_answer')!==null?(string)$req->json('text_answer'):null,$req->json('file_id')?(string)$req->json('file_id'):null);Response::success(['submission'=>$row],$req->requestId,201);}catch(\Throwable $x){Response::error('DB_ERROR','Could not submit homework',$req->requestId,500);}}});
};
